R.Locales = strings
function R.L(key, ...)
    local language = R.db and R.db.language or "EN"
    local value = (strings[language] and strings[language][key]) or strings.EN[key] or key
    if select("#", ...) > 0 then return string.format(value, ...) end
    return value
end
